PRAGMA foreign_keys=ON;
CREATE TABLE sources(source_id TEXT PRIMARY KEY,description TEXT NOT NULL,source_revision TEXT NOT NULL,input_sha256 TEXT NOT NULL,method_note TEXT NOT NULL);
CREATE TABLE stocks(stock_id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE records(source_id TEXT NOT NULL REFERENCES sources,record_id TEXT NOT NULL,stock_id TEXT NOT NULL REFERENCES stocks,created_date TEXT NOT NULL,trading_date TEXT,record_type TEXT NOT NULL,parent_record_id TEXT,text_norm TEXT NOT NULL,text_status TEXT NOT NULL,text_excel_escaped INTEGER NOT NULL CHECK(text_excel_escaped IN(0,1)),classification_status TEXT NOT NULL CHECK(classification_status IN('classified','unclassified')),relevance TEXT CHECK(relevance IN('related','unrelated','unclear')),sentiment TEXT CHECK(sentiment IN('긍정','중립','부정','혼합','판단유보')),model_name TEXT,CHECK((classification_status='unclassified' AND relevance IS NULL AND sentiment IS NULL) OR (classification_status='classified' AND relevance IS NOT NULL AND sentiment IS NOT NULL)),CHECK(relevance IS NULL OR relevance='related' OR sentiment='판단유보'),CHECK(text_status='available' OR text_norm=''),PRIMARY KEY(source_id,record_id));
CREATE INDEX records_stock_date ON records(stock_id,created_date);
CREATE INDEX records_status ON records(classification_status,stock_id);
CREATE INDEX records_sentiment ON records(sentiment,stock_id);
CREATE TABLE market_daily(source_id TEXT NOT NULL REFERENCES sources,stock_id TEXT NOT NULL REFERENCES stocks,trading_date TEXT NOT NULL,close REAL NOT NULL,volume INTEGER NOT NULL,same_day_return_pct REAL,next_day_return_pct REAL,market_source TEXT NOT NULL,PRIMARY KEY(source_id,stock_id,trading_date));
CREATE TABLE session_daily(source_id TEXT NOT NULL REFERENCES sources,stock_id TEXT NOT NULL REFERENCES stocks,date TEXT NOT NULL,session TEXT NOT NULL CHECK(session IN('pre','during','after')),observed_posts INTEGER NOT NULL,classified INTEGER NOT NULL,unclassified INTEGER NOT NULL,eligible INTEGER NOT NULL,positive INTEGER NOT NULL,neutral INTEGER NOT NULL,negative INTEGER NOT NULL,score REAL,same_day_open_close_return_pct REAL,overnight_return_pct REAL,next_day_open_close_return_pct REAL,PRIMARY KEY(source_id,stock_id,date,session));
CREATE VIEW stock_summary AS SELECT r.source_id,r.stock_id,s.name,COUNT(*) AS records,MIN(created_date) AS first_date,MAX(created_date) AS last_date,SUM(classification_status='classified') AS classified,SUM(classification_status='unclassified') AS unclassified,SUM(text_status='available') AS text_available FROM records r JOIN stocks s USING(stock_id) GROUP BY r.source_id,r.stock_id;
CREATE VIEW daily_sentiment AS SELECT source_id,stock_id,trading_date,COUNT(*) AS observed_records,SUM(classification_status='classified') AS classified,SUM(classification_status='unclassified') AS unclassified,COALESCE(SUM(relevance='related' AND sentiment IN('긍정','중립','부정')),0) AS eligible,COALESCE(SUM(relevance='related' AND sentiment='긍정'),0) AS positive,COALESCE(SUM(relevance='related' AND sentiment='부정'),0) AS negative,CASE WHEN SUM(classification_status='unclassified')=0 AND COALESCE(SUM(relevance='related' AND sentiment IN('긍정','중립','부정')),0)>=5 THEN 1.0*(COALESCE(SUM(relevance='related' AND sentiment='긍정'),0)-COALESCE(SUM(relevance='related' AND sentiment='부정'),0))/COALESCE(SUM(relevance='related' AND sentiment IN('긍정','중립','부정')),0) ELSE NULL END AS score FROM records WHERE trading_date IS NOT NULL GROUP BY source_id,stock_id,trading_date;
